const dbUrl = new URL(process.env.DATABASE_URL || 'mysql://root@localhost/question_grove_360');
const connection = await mysql.createConnection({
  host: dbUrl.hostname,
  user: dbUrl.username,
  password: dbUrl.password,
  database: dbUrl.pathname.slice(1),
});

try {
  let inserted = 0;
  for (const card of flashcardsData) {
    const query = `
      INSERT INTO flashcards (
        examId, specialty, pattern, answer, explanation, difficulty, status, front, back, category
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `;
    
    await connection.execute(query, [
      1, // examId
      card.specialty,
      card.pattern,
      card.answer,
      card.explanation,
      card.difficulty,
      'active',
      card.pattern, // front
      card.answer, // back
      card.specialty, // category
    ]);
    inserted++;
  }
  
  console.log(`✅ Successfully seeded ${inserted} flashcards`);
  
  // Verify counts by specialty
  const [results] = await connection.execute(`
    SELECT specialty, COUNT(*) as count FROM flashcards WHERE examId=1 GROUP BY specialty ORDER BY specialty
  `);
  
  console.log('\n📊 Flashcards by specialty:');
  results.forEach(row => {
    console.log(`  ${row.specialty}: ${row.count} cards`);
  });
  
  const [totalResult] = await connection.execute(`
    SELECT COUNT(*) as total FROM flashcards WHERE examId=1
  `);
  
  console.log(`\n✅ Total flashcards: ${totalResult[0].total}`);
} catch (error) {
  console.error('❌ Error seeding flashcards:', error.message);
  process.exit(1);
} finally {
  await connection.end();
}
